#!/usr/bin/env python3
"""Regenerate the app's bundled data from the Omniverse generated files.

Usage:  python3 tools/sync_data.py [path/to/dungeons.json] [path/to/world.json]

Writes app/src/main/assets/dungeons.js (window.BUNDLED_DUNGEONS) and
app/src/main/assets/world.js (window.BUNDLED_WORLD: the note kinds the app shows).
By default it reads <repo root>/_generated/ (this app lives in <repo root>/Apps/dmScreen).
Run `python3 _rules/tools/build_all.py .` first if the generated files are out of date.
"""
import json
import sys
from pathlib import Path

WORLD_KINDS = {"universe", "settlement", "venue", "person", "faction", "quest", "table", "item", "monster", "deity", "holiday", "region"}
WORLD_DATA_FIELDS = {
    "universe": ["tone", "ruleset", "status"],
    "settlement": ["size_class", "population", "ruler", "venues", "factions", "notable_people", "nearest_dungeons", "trade", "law", "rumours", "hooks"],
    "venue": ["venue_type", "keeper", "faction", "services", "stock", "rumours", "hooks", "read_aloud", "dm_notes"],
    "person": ["species", "role", "faction", "location", "voice", "wants", "fears", "secret", "goals", "relationships", "stat_block", "stats", "player_character", "pregen"],
    "faction": ["faction_type", "reach", "base", "leader", "members", "goals", "methods", "assets", "allies", "rivals", "dungeons", "reputation", "secret", "hooks"],
    "quest": ["giver", "start", "level_range", "premise", "hooks", "stages", "rewards", "on_success", "on_failure", "factions", "dungeons", "status"],
    "table": ["category", "die", "where", "entries"],
    "item": ["item_type", "rarity", "attunement", "value_gp", "description", "mechanics", "curse", "history"],
    "monster": ["ruleset", "size", "type", "threat", "alignment", "tactics", "lore", "dnd5e", "six_sides", "core"],
    "deity": ["title", "domains", "tenets", "symbol", "church"],
    "holiday": ["when", "customs", "hooks", "observed_by"],
    "region": ["biome", "hazards"],
}

here = Path(__file__).resolve().parent
app = here.parent
gen = app.parent.parent / "_generated"
dsrc = Path(sys.argv[1]) if len(sys.argv) > 1 else gen / "dungeons.json"
wsrc = Path(sys.argv[2]) if len(sys.argv) > 2 else (dsrc.parent / "world.json")
assets = app / "app" / "src" / "main" / "assets"


def read_aloud_of(body):
    for line in (body or "").splitlines():
        if line.startswith("> "):
            return line[2:].strip()
    return ""


def slim_world(w):
    out = []
    for n in w["notes"]:
        if n["kind"] not in WORLD_KINDS:
            continue
        d = n.get("data") or {}
        keep = {k: d[k] for k in WORLD_DATA_FIELDS.get(n["kind"], []) if k in d}
        e = {"id": n["id"], "kind": n["kind"], "name": n["name"], "universe": n.get("universe"), "parent": n.get("parent"),
             "summary": n.get("summary") or "", "tags": n.get("tags") or [], "data": keep, "referencedBy": n.get("referencedBy") or []}
        if n["kind"] in ("settlement", "venue", "region"):
            e["readAloud"] = d.get("read_aloud") or read_aloud_of(n.get("body"))
        if n["kind"] in ("person", "faction", "quest", "deity", "item", "monster"):
            e["body"] = (n.get("body") or "")[:1500]
        out.append(e)
    return {"schema": w.get("schema"), "source": w.get("source"), "notes": out}


data = json.loads(dsrc.read_text(encoding="utf-8"))
if data.get("schema") != 1 or not isinstance(data.get("dungeons"), list):
    sys.exit("error: %s is not a schema-1 dungeon index" % dsrc)
codes = [d.get("code") for d in data["dungeons"]]
if len(set(codes)) != len(codes):
    sys.exit("error: dungeon codes are not unique: %s" % codes)
text = json.dumps(data, ensure_ascii=False, separators=(",", ":"))
(assets / "dungeons.js").write_text("/* generated by tools/sync_data.py from _generated/dungeons.json - do not edit */\nwindow.BUNDLED_DUNGEONS=" + text + ";\n", encoding="utf-8")
print("wrote assets/dungeons.js: %d dungeons, %d rooms, %d KB" % (len(data["dungeons"]), sum(len(d["rooms"]) for d in data["dungeons"]), (assets / "dungeons.js").stat().st_size // 1024))

if wsrc.exists():
    world = json.loads(wsrc.read_text(encoding="utf-8"))
    slim = slim_world(world)
    wtext = json.dumps(slim, ensure_ascii=False, separators=(",", ":"))
    (assets / "world.js").write_text("/* generated by tools/sync_data.py from _generated/world.json - do not edit */\nwindow.BUNDLED_WORLD=" + wtext + ";\n", encoding="utf-8")
    print("wrote assets/world.js: %d notes, %d KB" % (len(slim["notes"]), (assets / "world.js").stat().st_size // 1024))
else:
    print("no world.json beside %s; world.js not written" % dsrc)
